 RulesFixture(){cc->actor_ids={"leader","worker"};family.founder_actor_id="leader";catalog.policies.insert(policy.id,policy);MemberPolicy member_policy;member_policy.id="serving";oc.member_policies.insert(member_policy.id,member_policy);OrgMemberState member;member.id="head.member";member.organization_id="realm";member.actor_id="leader";member.policy_id=member_policy.id;oc.members.insert(member.id,member);org.members.insert(member.id,member);}
