 void actual_result(const PoliticsEffects& effects){auto r=std::make_shared<CommitResult>();r->ok=true;r->kind="political_dismiss";r->tick=common.tick();r->revision=++common.state().identity.revision;r->result_id=take(common.next_id("result"));auto d=std::make_shared<ReceiptDetails>();d->data=effects;r->details=d;common.state().request_sequences.set("leader",1);common.state().results.insert("leader:1",r);common.state().history.push_back({r->tick,r->kind,"leader",r->result_id,{}});take(bind_political_dismissal_result(common,state,effects.fact_ids[0],"leader",1,*r,result_matches));}
