 RulesFixture late;late.common.state().next_instance_id=std::numeric_limits<Integer>::max()-1;const auto number=late.common.state().next_instance_id;auto x=late.context();auto q=take(preview_political_dismissal_source(x,"leader",late.command()));auto bad=apply_political_dismissal_with_source(late.common,late.politics,late.org,late.state,x,"leader",late.command(),q);check(!bad.ok&&late.common.state().next_instance_id==number&&late.common.state().facts.empty()&&late.politics.facts.empty()&&late.state.dismissals.empty()&&late.org.offices.find("county.office")->holder_actor_id==std::optional<StableId>{"worker"},"late original Office ID failure restores Common and both old states");
